/// Drive: sexinput sends OP_AUTODEMO_TICK every 30 ticks.
/// Shell moves cursor right→down→left→up, 96px steps, 24 moves total.
/// Gate: SEXOS_CURSOR_AUTODEMO=1 at build time.
/// Decoupled from SEXOS_KEYBOARD_CURSOR: keyboard cursor fallback no longer implies autodemo.
/// NOT USB success. Zero behavior change when flags absent.
const CURSOR_AUTODEMO_ENABLED: bool =
    option_env!("SEXOS_CURSOR_AUTODEMO").is_some();
/// OP code: sexinput → silk-shell autonomous cursor demo tick.
pub const OP_AUTODEMO_TICK: u64 = 0x2A0;
/// Shell interaction state contract proof gate.
/// Default OFF. Emits bounded contract markers on existing interaction paths.
const SHELL_INTERACTION_CONTRACT_PROOF_ENABLED: bool =
    option_env!("SEXOS_SHELL_INTERACTION_CONTRACT_PROOF").is_some();
const CLICK_DRAG_PROOF_ENABLED: bool =
    option_env!("SEXOS_CLICK_DRAG_PROOF").is_some()
        || option_env!("SEXOS_SHELL_INTERACTION_CONTRACT_PROOF").is_some();
static mut SHELL_INTERACTION_CONTRACT_BEGIN_EMITTED: bool = false;
static mut SHELL_INTERACTION_CONTRACT_DONE_EMITTED: bool = false;
static mut SHELL_INTERACTION_CONTRACT_STAGE_MASK: u8 = 0;
static mut CLICK_FOCUS_PROOF_BEGIN_EMITTED: bool = false;
static mut DRAG_PROOF_BEGIN_EMITTED: bool = false;
static mut DRAG_CAPTURE_MOVE_SEEN: bool = false;
const SHELL_INTERACTION_STAGE_POINTER: u8 = 1 << 0;
const SHELL_INTERACTION_STAGE_CLICK: u8 = 1 << 1;
const SHELL_INTERACTION_STAGE_DRAG: u8 = 1 << 2;
const SHELL_INTERACTION_STAGE_KEY: u8 = 1 << 3;
const SHELL_INTERACTION_STAGE_NO_FOCUS_KEY: u8 = 1 << 4;
const SHELL_INTERACTION_STAGE_DEAD_GUARD: u8 = 1 << 5;

/// AP9: Surface ID lifetime input safety proof gate.
/// Build with SEXOS_SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF=1 to enable.
const SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF_ENABLED: bool =
    option_env!("SEXOS_SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF").is_some();
static mut SURFACE_ID_LIFETIME_PROOF_BEGIN_EMITTED: bool = false;
static mut SURFACE_ID_LIFETIME_PROOF_FOCUS_LIVE_SEEN: bool = false;
static mut SURFACE_ID_LIFETIME_PROOF_KEY_ROUTE_SEEN: bool = false;
static mut SURFACE_ID_LIFETIME_PROOF_CLICK_TARGET_SEEN: bool = false;
static mut SURFACE_ID_LIFETIME_PROOF_DRAG_TARGET_SEEN: bool = false;
static mut SURFACE_ID_LIFETIME_PROOF_DEAD_CLEAR_SEEN: bool = false;

/// AP10: Input route negative tests proof gate.
/// Build with SEXOS_INPUT_NEGATIVE_PROOF=1 to enable.
const INPUT_NEGATIVE_PROOF_ENABLED: bool =
    option_env!("SEXOS_INPUT_NEGATIVE_PROOF").is_some();
static mut INPUT_NEGATIVE_BEGIN_EMITTED: bool = false;
static mut INPUT_NEGATIVE_UNKNOWN_CLASS_SEEN: bool = false;
static mut INPUT_NEGATIVE_BAD_BUTTON_SEEN: bool = false;
static mut INPUT_NEGATIVE_BUTTON_UP_NO_CAPTURE_SEEN: bool = false;
static mut INPUT_NEGATIVE_DONE_EMITTED: bool = false;

unsafe fn input_negative_begin_once() {
    if !INPUT_NEGATIVE_PROOF_ENABLED || INPUT_NEGATIVE_BEGIN_EMITTED {
        return;
    }
    INPUT_NEGATIVE_BEGIN_EMITTED = true;
    serial_println!("[input.negative.once] ok=1 malformed_unavailable=1");
}

unsafe fn input_negative_mark_done() {
    if !INPUT_NEGATIVE_PROOF_ENABLED || INPUT_NEGATIVE_DONE_EMITTED {
        return;
    }
    // done fires when all 4 required markers (unknown_class, bad_button,
    // no_focus_key, button_up_no_capture) have been seen.
    if INPUT_NEGATIVE_UNKNOWN_CLASS_SEEN
        && INPUT_NEGATIVE_BAD_BUTTON_SEEN
        && INPUT_NEGATIVE_BUTTON_UP_NO_CAPTURE_SEEN
    {
        INPUT_NEGATIVE_DONE_EMITTED = true;
        serial_println!(
            "[input.negative.done] ok=1 unknown_class=1 bad_button=1 no_focus_key_reuse=1 dead_target_reuse=1 button_up_no_capture=1 malformed_unavailable=1"
        );
    }
}

unsafe fn surface_input_lifetime_begin_once() {
    if !SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF_ENABLED || SURFACE_ID_LIFETIME_PROOF_BEGIN_EMITTED {
        return;
    }
    SURFACE_ID_LIFETIME_PROOF_BEGIN_EMITTED = true;
    serial_println!("[surface.input_lifetime.begin] ok=1");
}

unsafe fn surface_input_lifetime_mark_focus_live(focused: u64, live: u8, ok: u8) {
    if !SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF_ENABLED { return; }
    if live == 1 && ok == 1 { SURFACE_ID_LIFETIME_PROOF_FOCUS_LIVE_SEEN = true; }
    serial_println!("[surface.input_lifetime.focus_live] focused={} live={} ok={}", focused, live, ok);
}

unsafe fn surface_input_lifetime_mark_key_route(target: u64, live: u8, routed: u8, ok: u8) {
    if !SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF_ENABLED { return; }
    if live == 1 && ok == 1 { SURFACE_ID_LIFETIME_PROOF_KEY_ROUTE_SEEN = true; }
    serial_println!("[surface.input_lifetime.key_route_guard] target={} live={} routed={} ok={}", target, live, routed, ok);
}

unsafe fn surface_input_lifetime_mark_click_target(target: u64, live: u8, committed: u8, ok: u8) {
    if !SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF_ENABLED { return; }
    if live == 1 && ok == 1 { SURFACE_ID_LIFETIME_PROOF_CLICK_TARGET_SEEN = true; }
    serial_println!("[surface.input_lifetime.click_target_guard] target={} live={} committed={} ok={}", target, live, committed, ok);
}

unsafe fn surface_input_lifetime_mark_drag_target(target: u64, live: u8, phase: &str, ok: u8) {
    if !SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF_ENABLED { return; }
    if live == 1 && ok == 1 { SURFACE_ID_LIFETIME_PROOF_DRAG_TARGET_SEEN = true; }
    serial_println!("[surface.input_lifetime.drag_target_guard] target={} live={} phase={} ok={}", target, live, phase, ok);
}

unsafe fn surface_input_lifetime_mark_dead_clear(target: u64) {
    if !SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF_ENABLED { return; }
    SURFACE_ID_LIFETIME_PROOF_DEAD_CLEAR_SEEN = true;
    serial_println!("[surface.input_lifetime.dead_clear] target={} cleared=1 ok=1", target);
}

unsafe fn surface_input_lifetime_try_done() {
    if !SURFACE_ID_LIFETIME_INPUT_SAFETY_PROOF_ENABLED { return; }
    // Done requires all four live-guard markers (focus, key, click, drag).
    // dead_clear is safety-ensuring but may not fire in every proof lane.
    if SURFACE_ID_LIFETIME_PROOF_FOCUS_LIVE_SEEN
        && SURFACE_ID_LIFETIME_PROOF_KEY_ROUTE_SEEN
        && SURFACE_ID_LIFETIME_PROOF_CLICK_TARGET_SEEN
        && SURFACE_ID_LIFETIME_PROOF_DRAG_TARGET_SEEN
    {
        serial_println!(
            "[surface.input_lifetime.done] ok=1 dead_clear={}",
            SURFACE_ID_LIFETIME_PROOF_DEAD_CLEAR_SEEN as u8
        );
    }
}

unsafe fn shell_interaction_contract_begin_once() {
    if !SHELL_INTERACTION_CONTRACT_PROOF_ENABLED || SHELL_INTERACTION_CONTRACT_BEGIN_EMITTED {
        return;
    }
    SHELL_INTERACTION_CONTRACT_BEGIN_EMITTED = true;
    serial_println!("[shell.interact.contract.begin] mode=proof ok=1");
}

unsafe fn click_drag_proof_begin_click_once() {
    if !CLICK_DRAG_PROOF_ENABLED || CLICK_FOCUS_PROOF_BEGIN_EMITTED {
        return;
    }
    CLICK_FOCUS_PROOF_BEGIN_EMITTED = true;
    serial_println!("[click.focus.proof.begin] ok=1");
}

unsafe fn click_drag_proof_begin_drag_once() {
    if !CLICK_DRAG_PROOF_ENABLED || DRAG_PROOF_BEGIN_EMITTED {
        return;
    }
    DRAG_PROOF_BEGIN_EMITTED = true;
    serial_println!("[drag.proof.begin] ok=1");
}

unsafe fn shell_interaction_contract_mark_stage(stage: u8) {
    if !SHELL_INTERACTION_CONTRACT_PROOF_ENABLED {
        return;
    }
    SHELL_INTERACTION_CONTRACT_STAGE_MASK |= stage;
}

unsafe fn shell_interaction_contract_try_done() {
    if !SHELL_INTERACTION_CONTRACT_PROOF_ENABLED || SHELL_INTERACTION_CONTRACT_DONE_EMITTED {
        return;
    }
    let required = SHELL_INTERACTION_STAGE_POINTER
        | SHELL_INTERACTION_STAGE_CLICK
        | SHELL_INTERACTION_STAGE_DRAG
        | SHELL_INTERACTION_STAGE_KEY;
    if (SHELL_INTERACTION_CONTRACT_STAGE_MASK & required) == required {
        SHELL_INTERACTION_CONTRACT_DONE_EMITTED = true;
        serial_println!(
            "[shell.interact.contract.done] pointer=1 click=1 drag=1 key=1 dead_guard={} no_focus_key={} ok=1",
            ((SHELL_INTERACTION_CONTRACT_STAGE_MASK & SHELL_INTERACTION_STAGE_DEAD_GUARD) != 0) as u8,
            ((SHELL_INTERACTION_CONTRACT_STAGE_MASK & SHELL_INTERACTION_STAGE_NO_FOCUS_KEY) != 0) as u8
        );
    }
}

