/// Minimal Atlas drag intent state for Phase E3 proof markers.
/// Does NOT drive actual frame movement or ownership mutation.
struct AtlasDragIntent {
    active: bool,
    scene_id: u8,
    frame_id: u32,
    start_x: i32,
    start_y: i32,
}
static mut ATLAS_DRAG_INTENT: AtlasDragIntent = AtlasDragIntent {
    active: false,
    scene_id: 0,
    frame_id: 0,
    start_x: 0,
    start_y: 0,
};

