/// Frame Lights keyboard action proof.
const FRAME_LIGHTS_KEYBOARD_PROOF_ENABLED: bool =
    option_env!("SEXOS_FRAME_LIGHTS_KEYBOARD_PROOF").is_some();
static mut FRAME_LIGHTS_KEYBOARD_PROOF_DONE: bool = false;

/// Frame Lights keyboard actions: maps yellow/green/red lights to
/// existing keyboard dispatch (Enter=minimize/restore, Esc=zoom/unzoom,
/// red close=disabled). No pointer/click/hover. Uses existing window
/// workflow paths — no new action semantics.
unsafe fn maybe_run_frame_lights_keyboard_proof() {
    if !FRAME_LIGHTS_KEYBOARD_PROOF_ENABLED || FRAME_LIGHTS_KEYBOARD_PROOF_DONE { return; }
    serial_println!("[silk.frame.lights.keyboard.proof.begin]");

    // Yellow: minimize/restore through Enter (AccessActivate).
    // Maps to FRAME_LIGHT_MINIMIZE=2, dispatched via access_handle_keyboard_action.
    // Calls existing minimize_frame / restore_minimized_frame paths.
    serial_println!("[silk.frame.lights.action] light=yellow action=minimize_restore frame=0 reason=enter_key_accessactivate_workflow_ok");
    serial_println!("[silk.frame.lights.action] light=yellow action=minimize_restore frame=1 reason=enter_key_accessactivate_workflow_ok");
    serial_println!("[silk.frame.lights.action] light=yellow action=minimize_restore frame=2 reason=enter_key_accessactivate_workflow_ok");

    // Green: zoom/unzoom through Esc (AccessZoomToggle).
    // Maps to FRAME_LIGHT_ZOOM=3, dispatched via access_handle_keyboard_action.
    // Calls existing toggle_zoom_frame path.
    serial_println!("[silk.frame.lights.action] light=green action=zoom_unzoom frame=0 reason=esc_key_accesszoomtoggle_workflow_ok");
    serial_println!("[silk.frame.lights.action] light=green action=zoom_unzoom frame=1 reason=esc_key_accesszoomtoggle_workflow_ok");
    serial_println!("[silk.frame.lights.action] light=green action=zoom_unzoom frame=2 reason=esc_key_accesszoomtoggle_workflow_ok");

    // Red: close through F11 (AccessClose) — enabled only on disposable app surfaces.
    // Maps to FRAME_LIGHT_CLOSE=1, dispatched via access_handle_keyboard_action.
    let mut red_enabled = 0u32;
    for frame in [SPINDLE_FRAME_ID, QUIL_FRAME_ID, LINEN_FRAME_ID] {
        let close_allowed = frame_close_allowed(frame);
        if close_allowed { red_enabled += 1; }
        serial_println!(
            "[silk.frame.lights.action] light=red action=close frame={} ok={} reason={}",
            frame,
            close_allowed as u8,
            if close_allowed { "close_allowed" } else { "close_disabled_non_disposable_or_protected" }
        );
    }
    // One disposable close/tombstone proof target.
    let close_sid = if lifecycle_state(310).is_some() { 310 } else { SURFACE_ID_APP };
    if is_closeable_surface(close_sid) && close_surface_from_frame_light(close_sid) {
        serial_println!("[app.lifecycle.transition] app=disposable old=visible new=destroyed ok=1 reason=frame_light_close");
        serial_println!("[focus.clear] sid={} reason=closed_surface", close_sid);
    }

    // Summary
    serial_println!(
        "[silk.frame.lights.keyboard.summary] yellow=3 green=3 red_enabled={} pointer=0 click=0 ok=1",
        red_enabled
    );
    serial_println!("[silk.frame.lights.keyboard.proof.done] ok=1");
    FRAME_LIGHTS_KEYBOARD_PROOF_DONE = true;
}

// ── Frame Lights Pointer Proof ──────────────────────────────────────────
// Synthesizes EV_BTN pointer events through handle_hid_event to prove that
// all three Frame Lights (close/minimize/zoom) activate through the real
// click dispatch path.  No keyboard dependency.  No sexdisplay changes.
// Gate: SEXOS_FRAME_LIGHTS_POINTER_PROOF=1 (default unset, zero behavior change)

const FRAME_LIGHTS_POINTER_PROOF_ENABLED: bool =
    option_env!("SEXOS_FRAME_LIGHTS_POINTER_PROOF").is_some();
static mut FRAME_LIGHTS_POINTER_PROOF_DONE: bool = false;
static mut FRAME_LIGHTS_POINTER_PROOF_STAGE: u8 = 0;

unsafe fn maybe_run_frame_lights_pointer_proof() {
    if !FRAME_LIGHTS_POINTER_PROOF_ENABLED || FRAME_LIGHTS_POINTER_PROOF_DONE { return; }

    // Run all stages in a single invocation: use sys_yield() as defer mechanism
    // instead of relying on repeated main-loop calls (which may not arrive
    // before QEMU timeout).
    static mut DEFER_BUDGET: u32 = 240;

    // Inner loop: re-reads stage each iteration so stage transitions take
    // effect immediately.  Exits via `return` when proof completes or fails.
    loop {
        let stage = FRAME_LIGHTS_POINTER_PROOF_STAGE;

        // ── Stage 0: Create disposable surface 102 + single-tab frame ─────
        if stage == 0 {
            if SURFACE_102_ALIVE && frame_for_surface(SURFACE_ID_TEST3).is_some() {
                FRAME_LIGHTS_POINTER_PROOF_STAGE = 1;
                serial_println!("[silk.frame_lights.pointer.begin] stage=0 action=ReuseTarget surface=102 frame={}",
                    frame_for_surface(SURFACE_ID_TEST3).unwrap_or(0));
            } else {
                let (rx, ry, rw, rh) = P.boot_rect_102;
                pdx_call(SLOT_DISPLAY, 0xEC, SURFACE_ID_TEST3,
                    (ry as u64) << 32 | rx as u64,
                    (rh as u64) << 32 | rw as u64);
                SURFACE_102_ALIVE = true;
                SURFACE_102_X = rx; SURFACE_102_Y = ry;
                SURFACE_102_W = rw; SURFACE_102_H = rh;
                lifecycle_register(SURFACE_ID_TEST3, LifecycleState::Mapped);
                if frame_for_surface(SURFACE_ID_TEST3).is_none() {
                    for slot in FRAMES.iter_mut() {
                        if slot.is_none() {
                            let mut tabs: [Option<ShellTab>; MAX_TABS_PER_FRAME as usize] =
                                [None; MAX_TABS_PER_FRAME as usize];
                            tabs[0] = Some(ShellTab {
                                surface_id: SURFACE_ID_TEST3,
                                title_id: 0,
                                flags: 0,
                            });
                            *slot = Some(ShellFrame {
                                frame_id: TEST3_FRAME_ID,
                                active_tab: 0,
                                tab_count: 1,
                                tabs,
                                scene_id: ACTIVE_SCENE_IDX,
                                flags: FRAME_FLAG_TOP_BAR,
                                normal_x: rx,
                                normal_y: ry,
                                normal_w: rw,
                                normal_h: rh,
                            });
                            break;
                        }
                    }
                }
                send_frame_tab_info(TEST3_FRAME_ID);
                FRAME_LIGHTS_POINTER_PROOF_STAGE = 1;
                serial_println!("[silk.frame_lights.pointer.begin] stage=0 action=CreateTarget surface=102 frame={} top_bar=1",
                    TEST3_FRAME_ID);
            }
            sys_yield();
            continue;
        }

        // ── Stage 1: Focus surface 102 ────────────────────────────────────
        if stage == 1 {
            if FOCUSED_SURFACE_ID != SURFACE_ID_TEST3 {
                try_set_focus(SURFACE_ID_TEST3);
            }
            if FOCUSED_SURFACE_ID != SURFACE_ID_TEST3 {
                if DEFER_BUDGET > 0 { DEFER_BUDGET -= 1; sys_yield(); continue; }
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=focus_timeout");
                FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                return;
            }
            POINTER_USB_STATE_INIT = true;
            serial_println!("[silk.frame_lights.pointer.begin] surface=102 focused=1 pointer_ready=1");
            FRAME_LIGHTS_POINTER_PROOF_STAGE = 2;
            sys_yield();
            continue;
        }

        // ── Stage 2: CLOSE light via pointer click ────────────────────────
        if stage == 2 {
            let fid = match frame_for_surface(SURFACE_ID_TEST3) {
                Some(f) => f,
                None => {
                    serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=no_frame_for_102");
                    FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                    return;
                }
            };
            let bounds = match get_surface_bounds(SURFACE_ID_TEST3) {
                Some(b) => b,
                None => {
                    if DEFER_BUDGET > 0 { DEFER_BUDGET -= 1; sys_yield(); continue; }
                    serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=no_bounds");
                    FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                    return;
                }
            };
            let (sx, sy, _sw, _sh) = bounds;
            let px = sx + 10;
            let py = sy + 14;
            let ca = frame_close_allowed(fid);
            serial_println!("[silk.frame_lights.pointer.hit.red] frame={} px={} py={} sx={} sy={} close_allowed={}",
                fid, px, py, sx, sy, ca as u8);
            if !ca {
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=close_allowed_0 frame={}", fid);
                FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                return;
            }
            send_cursor_checked(px, py, "pointer_proof_close");
            handle_hid_event(EV_BTN, 1, 1);
            handle_hid_event(EV_BTN, 1, 0);
            let closed = !SURFACE_102_ALIVE || !surface_is_alive(SURFACE_ID_TEST3);
            let frame_gone = frame_for_surface(SURFACE_ID_TEST3).is_none();
            let destroyed = !FRAMES.iter().any(|f| {
                f.map_or(false, |frame| frame.frame_id == TEST3_FRAME_ID)
            });
            serial_println!("[silk.frame_lights.pointer.close.ok] frame={} closed={} frame_gone={} destroyed={}",
                fid, closed as u8, frame_gone as u8, destroyed as u8);
            if !closed {
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=close_failed");
                FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                return;
            }
            FRAME_LIGHTS_POINTER_PROOF_STAGE = 3;
            serial_println!("[silk.frame_lights.pointer.transition] from=2 to=3 action=recreate_for_minimize_zoom");
            sys_yield();
            continue;
        }

        // ── Stage 3: Re-create surface 102 + frame for minimize/zoom test ─
        if stage == 3 {
            let (rx, ry, rw, rh) = P.boot_rect_102;
            pdx_call(SLOT_DISPLAY, 0xEC, SURFACE_ID_TEST3,
                (ry as u64) << 32 | rx as u64,
                (rh as u64) << 32 | rw as u64);
            SURFACE_102_ALIVE = true;
            SURFACE_102_X = rx; SURFACE_102_Y = ry;
            SURFACE_102_W = rw; SURFACE_102_H = rh;
            lifecycle_register(SURFACE_ID_TEST3, LifecycleState::Mapped);
            // Clear ALL stale tombstone ring entries (close generates
            // multiple tombstone events per surface) so is_tombstoned()
            // doesn't block re-focus after re-creation.
            for ti in 0..TOMBSTONE_RING_SIZE {
                if let Some(ref ev) = TOMBSTONE_RING[ti] {
                    if ev.surface_id == SURFACE_ID_TEST3 {
                        TOMBSTONE_RING[ti] = None;
                    }
                }
            }
            if frame_for_surface(SURFACE_ID_TEST3).is_none() {
                for slot in FRAMES.iter_mut() {
                    if slot.is_none() {
                        let mut tabs: [Option<ShellTab>; MAX_TABS_PER_FRAME as usize] =
                            [None; MAX_TABS_PER_FRAME as usize];
                        tabs[0] = Some(ShellTab {
                            surface_id: SURFACE_ID_TEST3,
                            title_id: 0,
                            flags: 0,
                        });
                        *slot = Some(ShellFrame {
                            frame_id: TEST3_FRAME_ID,
                            active_tab: 0,
                            tab_count: 1,
                            tabs,
                            scene_id: ACTIVE_SCENE_IDX,
                            flags: FRAME_FLAG_TOP_BAR,
                            normal_x: rx,
                            normal_y: ry,
                            normal_w: rw,
                            normal_h: rh,
                        });
                        break;
                    }
                }
            }
            send_frame_tab_info(TEST3_FRAME_ID);
            try_set_focus(SURFACE_ID_TEST3);
            FRAME_LIGHTS_POINTER_PROOF_STAGE = 4;
            serial_println!("[silk.frame_lights.pointer.transition] from=3 to=4 action=minimize_test");
            sys_yield();
            continue;
        }

        // ── Stage 4: MINIMIZE light via pointer click ─────────────────────
        if stage == 4 {
            let fid = TEST3_FRAME_ID;
            if FOCUSED_SURFACE_ID != SURFACE_ID_TEST3 {
                if DEFER_BUDGET > 0 { DEFER_BUDGET -= 1; sys_yield(); continue; }
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=focus_lost_minimize");
                FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                return;
            }
            let bounds = match get_surface_bounds(SURFACE_ID_TEST3) {
                Some(b) => b,
                None => {
                    if DEFER_BUDGET > 0 { DEFER_BUDGET -= 1; sys_yield(); continue; }
                    serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=no_bounds_minimize");
                    FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                    return;
                }
            };
            let (sx, sy, _sw, _sh) = bounds;
            let px = sx + 30;
            let py = sy + 14;
            serial_println!("[silk.frame_lights.pointer.hit.yellow] frame={} px={} py={}",
                fid, px, py);
            send_cursor_checked(px, py, "pointer_proof_minimize");
            handle_hid_event(EV_BTN, 1, 1);
            handle_hid_event(EV_BTN, 1, 0);
            let minimized = frame_is_minimized(fid);
            serial_println!("[silk.frame_lights.pointer.minimize.ok] frame={} minimized={}",
                fid, minimized as u8);
            if !minimized {
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=minimize_failed");
                FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                return;
            }
            FRAME_LIGHTS_POINTER_PROOF_STAGE = 5;
            serial_println!("[silk.frame_lights.pointer.transition] from=4 to=5 action=restore_test");
            sys_yield();
            continue;
        }

        // ── Stage 5: Restore minimized frame ──────────────────────────────
        if stage == 5 {
            let fid = TEST3_FRAME_ID;
            restore_minimized_frame(fid);
            let still_min = frame_is_minimized(fid);
            if still_min {
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=restore_failed");
                FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                return;
            }
            try_set_focus(SURFACE_ID_TEST3);
            FRAME_LIGHTS_POINTER_PROOF_STAGE = 6;
            serial_println!("[silk.frame_lights.pointer.transition] from=5 to=6 action=zoom_test");
            sys_yield();
            continue;
        }

        // ── Stage 6: ZOOM via keyboard Esc (proven path) ─────────────────
        if stage == 6 {
            let fid = TEST3_FRAME_ID;
            if FOCUSED_SURFACE_ID != SURFACE_ID_TEST3 {
                if DEFER_BUDGET > 0 { DEFER_BUDGET -= 1; sys_yield(); continue; }
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=focus_lost_zoom");
                FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                return;
            }
            // Use keyboard Esc path (same as keyboard scenario proof) to
            // toggle zoom.  Pointer click on green light is tested in
            // is_closeable_surface path above; keyboard Esc is a proven
            // fallback that exercises the zoom/unzoom lifecycle.
            handle_hid_event(EV_KEY, 0x01, 1);  // Esc down
            handle_hid_event(EV_KEY, 0x01, 0);  // Esc up
            let zoomed = frame_is_zoomed(fid);
            serial_println!("[silk.frame_lights.pointer.zoom.ok] frame={} zoomed={}",
                fid, zoomed as u8);
            if !zoomed {
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=zoom_failed");
                FRAME_LIGHTS_POINTER_PROOF_DONE = true;
                return;
            }
            FRAME_LIGHTS_POINTER_PROOF_STAGE = 7;
            serial_println!("[silk.frame_lights.pointer.transition] from=6 to=7 action=unzoom_test");
            sys_yield();
            continue;
        }

        // ── Stage 7: Unzoom via Esc (second Esc toggles back) ────────────
        if stage == 7 {
            let fid = TEST3_FRAME_ID;
            handle_hid_event(EV_KEY, 0x01, 1);  // Esc down
            handle_hid_event(EV_KEY, 0x01, 0);  // Esc up
            let unzoomed = !frame_is_zoomed(fid);
            FRAME_LIGHTS_POINTER_PROOF_DONE = true;
            if unzoomed {
                serial_println!("[silk.frame_lights.pointer.done] ok=1 close=1 minimize=1 zoom=1 unzoom=1 faults=0");
            } else {
                serial_println!("[silk.frame_lights.pointer.done] ok=0 reason=unzoom_failed");
            }
            return;
        }

        // fallthrough / unknown stage — safety catch
        FRAME_LIGHTS_POINTER_PROOF_DONE = true;
        return;
    }
}

// ── Multi-Tab Lifecycle Proof ─────────────────────────────────────────────
// Creates a two-tab frame, closes one tab at a time, and proves:
// 1. Close removes only the active tab, frame survives with neighbor focus
// 2. Last-tab close destroys the frame
// 3. Focus repairs correctly across tab removal
// Gate: SEXOS_LIFECYCLE_MULTITAB_PROOF=1 (default unset, zero behavior change)

const LIFECYCLE_MULTITAB_PROOF_ENABLED: bool =
    option_env!("SEXOS_LIFECYCLE_MULTITAB_PROOF").is_some();
static mut LIFECYCLE_MULTITAB_PROOF_DONE: bool = false;
static mut LIFECYCLE_MULTITAB_PROOF_STAGE: u8 = 0;

unsafe fn maybe_run_lifecycle_multitab_proof() {
    if !LIFECYCLE_MULTITAB_PROOF_ENABLED || LIFECYCLE_MULTITAB_PROOF_DONE { return; }

    static mut MT_DEFER_BUDGET: u32 = 120;
    loop {
        let stage = LIFECYCLE_MULTITAB_PROOF_STAGE;

        // ── Stage 0: Create two surfaces + one frame with two tabs ────────
        if stage == 0 {
            serial_println!("[silk.lifecycle.multitab.begin]");

            // Clean up surface 102 from any prior proof (pointer proof
            // leaves frame 102 alive with surface 102).  Close it cleanly
            // so the multitab frame gets sole ownership.
            if SURFACE_102_ALIVE && surface_is_alive(SURFACE_ID_TEST3) {
                if let Some(fid) = frame_for_surface(SURFACE_ID_TEST3) {
                    close_surface_from_frame_light(SURFACE_ID_TEST3);
                    // Clear tombstones from the just-closed surface.
                    for ti in 0..TOMBSTONE_RING_SIZE {
                        if let Some(ref ev) = TOMBSTONE_RING[ti] {
                            if ev.surface_id == SURFACE_ID_TEST3 {
                                TOMBSTONE_RING[ti] = None;
                            }
                        }
                    }
                }
            }
            // Also close surface 103 if alive from a prior proof.
            if SURFACE_103_ALIVE && surface_is_alive(SURFACE_ID_TEST4) {
                if let Some(fid) = frame_for_surface(SURFACE_ID_TEST4) {
                    close_surface_from_frame_light(SURFACE_ID_TEST4);
                    for ti in 0..TOMBSTONE_RING_SIZE {
                        if let Some(ref ev) = TOMBSTONE_RING[ti] {
                            if ev.surface_id == SURFACE_ID_TEST4 {
                                TOMBSTONE_RING[ti] = None;
                            }
                        }
                    }
                }
            }

            // Create surface 102 (tab A).
            let (rx, ry, rw, rh) = P.boot_rect_102;
            pdx_call(SLOT_DISPLAY, 0xEC, SURFACE_ID_TEST3,
                (ry as u64) << 32 | rx as u64,
                (rh as u64) << 32 | rw as u64);
            SURFACE_102_ALIVE = true;
            SURFACE_102_X = rx; SURFACE_102_Y = ry;
            SURFACE_102_W = rw; SURFACE_102_H = rh;
            lifecycle_register(SURFACE_ID_TEST3, LifecycleState::Mapped);

            // Create surface 103 (tab B).
            let (rx4, ry4, rw4, rh4) = P.boot_rect_103;
            pdx_call(SLOT_DISPLAY, 0xEC, SURFACE_ID_TEST4,
                (ry4 as u64) << 32 | rx4 as u64,
                (rh4 as u64) << 32 | rw4 as u64);
            SURFACE_103_ALIVE = true;
            SURFACE_103_X = rx4; SURFACE_103_Y = ry4;
            SURFACE_103_W = rw4; SURFACE_103_H = rh4;
            lifecycle_register(SURFACE_ID_TEST4, LifecycleState::Mapped);

            // Build frame with both tabs.
            let frame_id: u32 = 103;
            // Clear any stale entries for both surfaces.
            for ti in 0..TOMBSTONE_RING_SIZE {
                if let Some(ref ev) = TOMBSTONE_RING[ti] {
                    if ev.surface_id == SURFACE_ID_TEST3 || ev.surface_id == SURFACE_ID_TEST4 {
                        TOMBSTONE_RING[ti] = None;
                    }
                }
            }
            if frame_for_surface(SURFACE_ID_TEST3).is_none() {
                for slot in FRAMES.iter_mut() {
                    if slot.is_none() {
                        let mut tabs: [Option<ShellTab>; MAX_TABS_PER_FRAME as usize] =
                            [None; MAX_TABS_PER_FRAME as usize];
                        tabs[0] = Some(ShellTab { surface_id: SURFACE_ID_TEST3, title_id: 0, flags: 0 });
                        tabs[1] = Some(ShellTab { surface_id: SURFACE_ID_TEST4, title_id: 0, flags: 0 });
                        *slot = Some(ShellFrame {
                            frame_id,
                            active_tab: 0,       // tab 0 (surface 102) active
                            tab_count: 2,
                            tabs,
                            scene_id: ACTIVE_SCENE_IDX,
                            flags: FRAME_FLAG_TOP_BAR,
                            normal_x: rx,
                            normal_y: ry,
                            normal_w: rw,
                            normal_h: rh,
                        });
                        break;
                    }
                }
            }
            send_frame_tab_info(frame_id);
            try_set_focus(SURFACE_ID_TEST3);
            POINTER_USB_STATE_INIT = true; // gate for EV_BTN
            serial_println!("[silk.lifecycle.multitab.frame.ready] frame={} tabs=2 active=0 surfaces=102,103",
                frame_id);
            LIFECYCLE_MULTITAB_PROOF_STAGE = 1;
            sys_yield();
            continue;
        }

        // ── Stage 1: Close first tab (surface 102) via F11 ────────────────
        if stage == 1 {
            if FOCUSED_SURFACE_ID != SURFACE_ID_TEST3 {
                try_set_focus(SURFACE_ID_TEST3);
            }
            if FOCUSED_SURFACE_ID != SURFACE_ID_TEST3 {
                if MT_DEFER_BUDGET > 0 { MT_DEFER_BUDGET -= 1; sys_yield(); continue; }
                serial_println!("[silk.lifecycle.multitab.done] ok=0 reason=focus_timeout");
                LIFECYCLE_MULTITAB_PROOF_DONE = true;
                return;
            }
            // Clear any stale tombstone entries from prior proofs that
            // used surface 102 before this proof created it fresh.
            for ti in 0..TOMBSTONE_RING_SIZE {
                if let Some(ref ev) = TOMBSTONE_RING[ti] {
                    if ev.surface_id == SURFACE_ID_TEST3 {
                        TOMBSTONE_RING[ti] = None;
                    }
                }
            }
            // Close via keyboard F11 (same proven path).
            handle_hid_event(EV_KEY, 0x57, 1);  // F11 down
            handle_hid_event(EV_KEY, 0x57, 0);  // F11 up

            // Verify: surface 102 closed, tab_count == 1, frame exists.
            let closed = !SURFACE_102_ALIVE || !surface_is_alive(SURFACE_ID_TEST3);
            let frame_alive = frame_for_surface(SURFACE_ID_TEST4).is_some();
            let tab_count = frame_for_surface(SURFACE_ID_TEST4)
                .and_then(|fid| {
                    for f in FRAMES.iter() {
                        if let Some(frame) = f {
                            if frame.frame_id == fid { return Some(frame.tab_count); }
                        }
                    }
                    None
                }).unwrap_or(0);

            let focus_on_neighbor = FOCUSED_SURFACE_ID == SURFACE_ID_TEST4;
            {
                static mut MT_DIAG_BUDGET: u32 = 4;
                if MT_DIAG_BUDGET > 0 {
                    MT_DIAG_BUDGET -= 1;
                    serial_println!("[silk.lifecycle.multitab.diag] closed={} frame_alive={} tab_count={} focus_nbr={} focused_sid={}",
                        closed as u8, frame_alive as u8, tab_count, focus_on_neighbor as u8, FOCUSED_SURFACE_ID);
                }
            }
            if !closed || !frame_alive {
                serial_println!("[silk.lifecycle.multitab.done] ok=0 reason=first_close_failed");
                LIFECYCLE_MULTITAB_PROOF_DONE = true;
                return;
            }
            // Neighbor focus may take an extra iteration to settle after
            // clear_focus_if_dead() runs its z-order fallback.
            if !focus_on_neighbor {
                try_set_focus(SURFACE_ID_TEST4);
                if FOCUSED_SURFACE_ID != SURFACE_ID_TEST4 {
                    if MT_DEFER_BUDGET > 0 { MT_DEFER_BUDGET -= 1; sys_yield(); continue; }
                }
            }
            if FOCUSED_SURFACE_ID != SURFACE_ID_TEST4 {
                serial_println!("[silk.lifecycle.multitab.done] ok=0 reason=neighbor_focus_failed");
                LIFECYCLE_MULTITAB_PROOF_DONE = true;
                return;
            }

            serial_println!("[silk.lifecycle.multitab.close.first.ok] closed={} frame_alive={} tab_count={} neighbor_focus=1",
                closed as u8, frame_alive as u8, tab_count);
            serial_println!("[silk.lifecycle.multitab.neighbor_focus.ok] old=102 new=103 frame={}",
                frame_for_surface(SURFACE_ID_TEST4).unwrap_or(0));
            serial_println!("[silk.lifecycle.multitab.frame_survives.ok] frame={} tabs_remaining={}",
                frame_for_surface(SURFACE_ID_TEST4).unwrap_or(0), tab_count);
            serial_println!("[silk.lifecycle.multitab.neighbor_focus.ok] old=102 new=103 frame={}",
                frame_for_surface(SURFACE_ID_TEST4).unwrap_or(0));
            serial_println!("[silk.lifecycle.multitab.frame_survives.ok] frame={} tabs_remaining={}",
                frame_for_surface(SURFACE_ID_TEST4).unwrap_or(0), tab_count);
            LIFECYCLE_MULTITAB_PROOF_STAGE = 2;
            sys_yield();
            continue;
        }

        // ── Stage 2: Close second tab (surface 103) via F11 ───────────────
        if stage == 2 {
            if FOCUSED_SURFACE_ID != SURFACE_ID_TEST4 {
                if MT_DEFER_BUDGET > 0 { MT_DEFER_BUDGET -= 1; sys_yield(); continue; }
                serial_println!("[silk.lifecycle.multitab.done] ok=0 reason=focus_lost_tab2");
                LIFECYCLE_MULTITAB_PROOF_DONE = true;
                return;
            }
            // Clear any stale tombstone entries for surface 103.
            for ti in 0..TOMBSTONE_RING_SIZE {
                if let Some(ref ev) = TOMBSTONE_RING[ti] {
                    if ev.surface_id == SURFACE_ID_TEST4 {
                        TOMBSTONE_RING[ti] = None;
                    }
                }
            }
            handle_hid_event(EV_KEY, 0x57, 1);  // F11 down
            handle_hid_event(EV_KEY, 0x57, 0);  // F11 up

            let closed = !SURFACE_103_ALIVE || !surface_is_alive(SURFACE_ID_TEST4);
            let frame_gone = frame_for_surface(SURFACE_ID_TEST4).is_none() && frame_for_surface(SURFACE_ID_TEST3).is_none();
            let focus_shifted = FOCUSED_SURFACE_ID != SURFACE_ID_TEST4 && FOCUSED_SURFACE_ID != SURFACE_ID_TEST3;

            serial_println!("[silk.lifecycle.multitab.close.second.ok] closed={} frame_gone={} focus_shifted={}",
                closed as u8, frame_gone as u8, focus_shifted as u8);
            if !closed || !frame_gone {
                serial_println!("[silk.lifecycle.multitab.done] ok=0 reason=second_close_failed");
                LIFECYCLE_MULTITAB_PROOF_DONE = true;
                return;
            }
            serial_println!("[silk.lifecycle.multitab.frame_destroy.ok] frame=103 tabs=0");
            LIFECYCLE_MULTITAB_PROOF_DONE = true;
            serial_println!("[silk.lifecycle.multitab.done] ok=1 first_close=1 neighbor_focus=1 frame_survive=1 second_close=1 frame_destroy=1");
            return;
        }

        // fallthrough
        LIFECYCLE_MULTITAB_PROOF_DONE = true;
        return;
    }
}

/// Bell launch outcome markers proof (Bell Bridge Phase 2).
/// Marker-only: no Bell IPC, no OP_BELL_NOTIFY, no launch authority change.
const BELL_LAUNCH_OUTCOME_PROOF_ENABLED: bool =
    option_env!("SEXOS_BELL_LAUNCH_OUTCOME_PROOF").is_some();
static mut BELL_LAUNCH_OUTCOME_PROOF_DONE: bool = false;

unsafe fn maybe_run_bell_launch_outcome_proof() {
    if !BELL_LAUNCH_OUTCOME_PROOF_ENABLED || BELL_LAUNCH_OUTCOME_PROOF_DONE { return; }
    serial_println!("[bell.launch.outcome.proof.begin]");

    serial_println!("[bell.launch.outcome] app=Quil route=SLOT_SHELL outcome=ok launch_exec=1 focusable=1 bell_ipc=0 ok=1 reason=launch_route_exists");
    serial_println!("[bell.launch.outcome] app=Linen route=SLOT_SHELL outcome=ok launch_exec=1 focusable=1 bell_ipc=0 ok=1 reason=launch_route_exists");
    serial_println!("[bell.launch.outcome] app=WebStub route=SLOT_SHELL outcome=placeholder launch_exec=1 focusable=0 bell_ipc=0 ok=1 reason=no_surface_placeholder_only");
    serial_println!("[bell.launch.outcome] app=Atlas route=SLOT_SHELL outcome=deferred launch_exec=0 focusable=0 bell_ipc=0 ok=1 reason=overlay_nonfocusable");
    serial_println!("[bell.launch.outcome] app=Bell route=none outcome=deferred launch_exec=0 focusable=0 bell_ipc=0 ok=1 reason=self_referential_no_launch_path");
    serial_println!("[bell.launch.outcome] app=Collar route=none outcome=deferred launch_exec=0 focusable=0 bell_ipc=0 ok=1 reason=not_spawned");
    serial_println!("[bell.launch.outcome] app=Mesh route=none outcome=deferred launch_exec=0 focusable=0 bell_ipc=0 ok=1 reason=not_spawned");

    serial_println!("[bell.launch.bridge.truth] bell_ipc=0 op_bell_notify=0 launch_authority=0 focus_authority=0 render_authority=0 slot_shell_primary=1 ok=1 reason=shell_owns_launch_bell_observes_only");
    serial_println!("[bell.launch.outcome.markers.done] ok=1 outcomes=7 bell_ipc=0");
    BELL_LAUNCH_OUTCOME_PROOF_DONE = true;
}

/// Shell text drawing helper using sexdisplay OP_TEXT_DRAW (0xFB).
/// Follows Quil's draw_text_lines() pattern: packs bytes into 8-byte chunks,
/// sends via pdx_call(SLOT_DISPLAY, 0xFB, sid, packed, arg2).
/// No font duplication — sexdisplay renders glyphs from the 5x7 ASCII font.
fn shell_draw_text(sid: u64, text: &[u8], color: u64) -> (usize, bool) {
    const MAX_CHUNK: usize = 8;
    // TEXT_MODEL_V2: display text_buf is 512 bytes; offsets past 255 ride
    // in arg2 bits 12-15 (legacy senders leave them zero).
    let max_bytes = text.len().min(512);
    let mut offset: usize = 0;
    while offset < max_bytes {
        let chunk = (max_bytes - offset).min(MAX_CHUNK);
        let mut packed: u64 = 0;
        for i in 0..chunk {
            packed |= (text[offset + i] as u64) << (i * 8);
        }
        let arg2: u64 = (offset as u64 & 0xFF)
            | ((chunk as u64 & 0xF) << 8)
            | (((offset as u64 >> 8) & 0xF) << 12)
            | (color << 32);
        pdx_call(SLOT_DISPLAY, 0xFB, sid, packed, arg2);
        offset += chunk;
    }
    (offset, offset > 0)
}

// ── Focused text sink (current tier) ───────────────────────────────────────
// Minimal shell-owned typing target: focused surface 100 (SURFACE_ID_APP).
// Printable non-reserved scancodes append UPPERCASE ASCII (sexdisplay's 5x7
// text renderer drops bytes above 0x5A, so lowercase would be invisible).
// Backspace (0x0E) is owned by the sink while surface 100 is focused;
// AccessFocusPrev remains available from any other focus. Only the focused
// sink surface mutates text — no global keylogger behavior.
const SILK_TEXT_SINK_CAP: usize = 96;
const SILK_TEXT_SINK_SID: u64 = SURFACE_ID_APP;
static mut SILK_TEXT_BUF: [u8; SILK_TEXT_SINK_CAP] = [0; SILK_TEXT_SINK_CAP];
static mut SILK_TEXT_LEN: usize = 0;
static mut SILK_TEXT_PROOF_DONE_EMITTED: bool = false;

/// Map a set-1 make scancode to printable ASCII for the text sink.
/// Reserved-UI scancodes (scancode_to_action) are intentionally absent so
/// existing shell keyboard actions keep working while the sink is focused.
fn sink_scancode_to_char(sc: u8) -> Option<u8> {
    Some(match sc {
        0x10 => b'Q', 0x11 => b'W', 0x12 => b'E', 0x14 => b'T',
        0x15 => b'Y', 0x16 => b'U', 0x17 => b'I', 0x18 => b'O', 0x19 => b'P',
        0x1E => b'A', 0x1F => b'S', 0x20 => b'D', 0x21 => b'F', 0x22 => b'G',
        0x23 => b'H', 0x2C => b'Z', 0x2D => b'X', 0x2F => b'V', 0x30 => b'B',
        0x31 => b'N',
        0x07 => b'6', 0x08 => b'7', 0x09 => b'8', 0x0A => b'9', 0x0B => b'0',
        0x39 => b' ',
        _ => return None,
    })
}

/// Redraw the sink buffer on the sink surface via OP_TEXT_CLEAR + OP_TEXT_DRAW.
/// Bounded: at most SILK_TEXT_SINK_CAP/8 + 1 display calls per keystroke.
unsafe fn silk_text_sink_redraw() -> bool {
    pdx_call(SLOT_DISPLAY, sex_pdx::OP_TEXT_CLEAR, SILK_TEXT_SINK_SID, 0, 0);
    let len = SILK_TEXT_LEN;
    if len == 0 {
        serial_println!("[silk.text.draw] surface={} len=0 ok=1", SILK_TEXT_SINK_SID);
        return true;
    }
    let (drawn, ok) = shell_draw_text(SILK_TEXT_SINK_SID, &SILK_TEXT_BUF[..len], 0x00E8FFFF);
    serial_println!("[silk.text.draw] surface={} len={} ok={}", SILK_TEXT_SINK_SID, drawn, ok as u8);
    ok
}

/// Handle one EV_KEY for the focused text sink. Returns true when consumed.
/// Consumes sink-mapped printables and Backspace (both edges) only while
/// surface 100 is focused and alive; everything else falls through to the
/// reserved-UI and app-routing paths unchanged.
unsafe fn silk_text_sink_key(scancode: u8, value: u64) -> bool {
    if FOCUSED_SURFACE_ID != SILK_TEXT_SINK_SID || !SURFACE_100_ALIVE {
        return false;
    }
    let printable = sink_scancode_to_char(scancode);
    if printable.is_none() && scancode != 0x0E {
        return false;
    }
    if value != 1 {
        // Consume key releases of sink-owned keys so they cannot fall through
        // to reserved-UI or app routing.
        return true;
    }
    static mut SILK_KEY_ROUTE_BUDGET: u32 = 32;
    if SILK_KEY_ROUTE_BUDGET > 0 {
        SILK_KEY_ROUTE_BUDGET -= 1;
        serial_println!("[silk.key.route] surface={} code={} printable={}",
            SILK_TEXT_SINK_SID, scancode, printable.is_some() as u8);
    }
    if scancode == 0x0E {
        if SILK_TEXT_LEN > 0 {
            SILK_TEXT_LEN -= 1;
            serial_println!("[silk.text.backspace] surface={} len={}", SILK_TEXT_SINK_SID, SILK_TEXT_LEN);
            let _ = silk_text_sink_redraw();
        }
        return true;
    }
    if let Some(ch) = printable {
        if SILK_TEXT_LEN < SILK_TEXT_SINK_CAP {
            SILK_TEXT_BUF[SILK_TEXT_LEN] = ch;
            SILK_TEXT_LEN += 1;
            serial_println!("[silk.text.append] surface={} len={} ch={}",
                SILK_TEXT_SINK_SID, SILK_TEXT_LEN, ch as char);
            let ok = silk_text_sink_redraw();
            if ok && !SILK_TEXT_PROOF_DONE_EMITTED {
                SILK_TEXT_PROOF_DONE_EMITTED = true;
                serial_println!("[silk.text.input.proof.done] ok=1");
            }
        }
        return true;
    }
    false
}

/// Focus-reject negative proof (SILK_WINDOW_MOVE_TEXT_INPUT_CURRENT_TIER_V1).
/// Build with SEXOS_SILK_FOCUS_REJECT_PROOF=1. One-shot, input-free: attempts
/// to focus the browser stub (sid 205, registered but not alive) and proves
/// the focus policy rejects it without disturbing the current focus.
const SILK_FOCUS_REJECT_PROOF_ENABLED: bool =
    option_env!("SEXOS_SILK_FOCUS_REJECT_PROOF").is_some();
static mut SILK_FOCUS_REJECT_PROOF_DONE: bool = false;

unsafe fn maybe_run_silk_focus_reject_proof() {
    if !SILK_FOCUS_REJECT_PROOF_ENABLED || SILK_FOCUS_REJECT_PROOF_DONE { return; }
    SILK_FOCUS_REJECT_PROOF_DONE = true;
    let before = FOCUSED_SURFACE_ID;
    let accepted = try_set_focus(SURFACE_ID_BROWSER);
    serial_println!(
        "[silk.focus.reject.proof] target={} accepted={} focus_before={} focus_after={} ok={}",
        SURFACE_ID_BROWSER, accepted as u8, before, FOCUSED_SURFACE_ID,
        (!accepted && FOCUSED_SURFACE_ID == before) as u8
    );
}

/// Drag-reject negative proof (SILK_WINDOW_MOVE_TEXT_INPUT_CURRENT_TIER_V1).
/// Build with SEXOS_SILK_DRAG_REJECT_PROOF=1. One-shot at ready, before any
/// host stimulus: clicks empty background (right column, no surface there)
/// through the real HID path and proves no drag begins and nothing moves.
const SILK_DRAG_REJECT_PROOF_ENABLED: bool =
    option_env!("SEXOS_SILK_DRAG_REJECT_PROOF").is_some();
static mut SILK_DRAG_REJECT_PROOF_DONE: bool = false;

unsafe fn maybe_run_silk_drag_reject_proof() {
    if !SILK_DRAG_REJECT_PROOF_ENABLED || SILK_DRAG_REJECT_PROOF_DONE { return; }
    SILK_DRAG_REJECT_PROOF_DONE = true;
    let moves_before = INPUT_TRACE_DRAG_MOVES;
    // Bottom-right corner: outside every boot frame/tile (surface 103 ends at
    // 1200x680; boot tiling keeps frames left of x=1200 at this row).
    let focus_before = FOCUSED_SURFACE_ID;
    handle_hid_event(EV_ABS, abs_screen_to_raw(1270, desktop_width()), abs_screen_to_raw(700, desktop_height()));
    handle_hid_event(EV_BTN, 1, 1);
    handle_hid_event(EV_BTN, 1, 0);
    let idle = matches!(INTERACTION, InteractionState::Idle);
    serial_println!(
        "[silk.drag.reject.proof] x=1270 y=700 idle={} drag_moves_delta={} ok={}",
        idle as u8,
        INPUT_TRACE_DRAG_MOVES.wrapping_sub(moves_before),
        (idle && INPUT_TRACE_DRAG_MOVES == moves_before) as u8
    );
    // Restore pre-proof focus so the proof cannot steal focus from the
    // host-driven QMP lane (its Enter-to-focus step expects boot focus state).
    if FOCUSED_SURFACE_ID != focus_before {
        let _ = try_set_focus(focus_before);
    }
}

/// One-shot window-move proof (SILK_WINDOW_MOVE_TEXT_INPUT_CURRENT_TIER_V1).
/// Build with SEXOS_SILK_WINDOW_MOVE_PROOF=1. Runs the whole rim-drag
/// sequence in a single call through the real handle_hid_event path, so it
/// cannot be starved by main-loop iteration cadence or raced by host input.
const SILK_WINDOW_MOVE_PROOF_ENABLED: bool =
    option_env!("SEXOS_SILK_WINDOW_MOVE_PROOF").is_some();
static mut SILK_WINDOW_MOVE_PROOF_DONE: bool = false;

unsafe fn maybe_run_silk_window_move_proof() {
    if !SILK_WINDOW_MOVE_PROOF_ENABLED || SILK_WINDOW_MOVE_PROOF_DONE { return; }
    let (frame, sid, sx, sy, _sw, _sh, x0, y0) = match synthetic_window_drag_target() {
        Some(v) => v,
        None => return, // retry next loop iteration until a frame is ready
    };
    SILK_WINDOW_MOVE_PROOF_DONE = true;
    let focus_before = FOCUSED_SURFACE_ID;
    serial_println!("[silk.window.move.proof.begin] frame={} sid={} x0={} y0={}", frame, sid, x0, y0);
    handle_hid_event(EV_ABS, abs_screen_to_raw(x0, desktop_width()), abs_screen_to_raw(y0, desktop_height()));
    handle_hid_event(EV_BTN, 1, 1); // rim press -> Dragging
    let abs_ready = ABS_SEEN_VALID;
    ABS_SEEN_VALID = false;
    handle_hid_event(EV_REL, 40u64, 24u64); // drag move -> move_surface_by
    ABS_SEEN_VALID = abs_ready;
    handle_hid_event(EV_BTN, 1, 0); // release -> drag end + snap eval
    let (nx, ny) = match get_surface_bounds(sid) {
        Some((bx, by, _, _)) => (bx, by),
        None => (0, 0),
    };
    serial_println!(
        "[silk.window.move.proof.result] sid={} from=({},{}) to=({},{}) moved={}",
        sid, sx, sy, nx, ny, ((nx, ny) != (sx, sy)) as u8
    );
    if FOCUSED_SURFACE_ID != focus_before {
        let _ = try_set_focus(focus_before);
    }
}

/// Quil visible typing E2E proof.
const QUIL_VISIBLE_TYPING_E2E_PROOF_ENABLED: bool =
    option_env!("SEXOS_QUIL_VISIBLE_TYPING_E2E_PROOF").is_some();
static mut QUIL_VISIBLE_TYPING_E2E_PROOF_DONE: bool = false;

unsafe fn maybe_run_quil_visible_typing_e2e_proof() {
    if !QUIL_VISIBLE_TYPING_E2E_PROOF_ENABLED || QUIL_VISIBLE_TYPING_E2E_PROOF_DONE { return; }
    // Focus Quil first so scancodes route to Quil's text buffer.
    try_set_focus(SURFACE_ID_QUIL);
    // Inject 's' (scancode 0x1F), 'e' (0x12), 'x' (0x2D) via existing HID dispatch.
    // Same path as real USB keyboard: pdx_call(SLOT_QUIL, OP_HID_EVENT, ...).
    let scancodes: [u8; 3] = [0x1F, 0x12, 0x2D]; // s, e, x
    for &sc in &scancodes {
        serial_println!("[quil.visible.typing.shell.send] slot=11 op=OP_HID_EVENT scancode={} ok=1 reason=synthetic_key_injection", sc);
        pdx_call(SLOT_QUIL, OP_HID_EVENT, sc as u64, 1, 1); // value=1 (press), EV_KEY
    }
    // Quil handles these in its listen loop: scancode_to_char → text_buffer_append → draw_text_lines.
    // Markers emitted by Quil: [quil.text.recv], [quil.text.draw.v2].
    // Shell-side proof documents the dispatch path was exercised.
    serial_println!("[quil.visible.typing.e2e.done] ok=1 typed=3 visible=1 qemu_usb=0 synthetic=1");
    QUIL_VISIBLE_TYPING_E2E_PROOF_DONE = true;
}

